ScriptGroup.script:
--Do not remove the following lines. Or change them.
demonnic = demonnic or {}
demonnic.chat = demonnic.chat or {}
demonnic.chat.tabsToBlink = demonnic.chat.tabsToBlink or {}
demonnic.chat.tabs = demonnic.chat.tabs or {}
demonnic.chat.windows = demonnic.chat.windows or {}
GUI.debug("YATCO/BOOT", "tabbed chat namespace loaded", {
  config = type(demonnic.chat.config),
  tabs = GUI.debugCountEntries(demonnic.chat.tabs),
  windows = GUI.debugCountEntries(demonnic.chat.windows),
})
if not demonnic.chat.config then
  cecho("<red:white>YOU DO NOT HAVE THE YATCO CONFIG PACKAGE IN PLACE. THINGS WILL NOT WORK AS EXPECTED\n\n")
  demonnic.chat.error = "NO CONFIG"
  GUI.debugError("YATCO/BOOT", "YATCO configuration table is missing")
end

Script.script:
function demonnicOnInstall(_, package)
  GUI.debug("YATCO/INSTALL", "sysInstall received", {
    package = package,
  })
  -- Check for both LuminariGUI and YATCO package names to handle mid-session imports
  if type(package) == "string" and
    (package:find("YATCO") or package:find("LuminariGUI")) then
    demonnicOnStart()
  end
end
